head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 Group 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';
    strGenerator += '<w2:windowContainer id="generator1_child" style="width:500px; height:300px; position:relative;" ev:onclick="scwin.generator1_child_onclick">';
    strGenerator += '<w2:windowToolbar>';
    strGenerator += '<w2:controlIconLayer>';
    strGenerator += '<w2:controlIcon></w2:controlIcon>';
    strGenerator += '<w2:controlIcon></w2:controlIcon>';
    strGenerator += '<w2:controlIcon></w2:controlIcon>';
    strGenerator += '<w2:controlIcon></w2:controlIcon>';
    strGenerator += '<w2:controlIcon></w2:controlIcon>';
    strGenerator += '</w2:controlIconLayer>';
    strGenerator += '<w2:nameLayer></w2:nameLayer>';
    strGenerator += '<w2:selectedNameLayer></w2:selectedNameLayer>';
    strGenerator += '</w2:windowToolbar>';
    strGenerator += '</w2:windowContainer>';
    strGenerator += '</w2:generator>';

    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp
    );

    // windowContainer 자식은 비동기 초기화되며, 동적 생성된 자식 템플릿의 clone 소스는 현재 렌더 사이클(onpageload)이
    //  끝난 뒤에야 준비된다. comp_init 을 await/for 로 블로킹하면 렌더가 진행되지 못해 계속 _cloneRecursive 로 실패하므로,
    //  setTimeout 으로 렌더 사이클 이후로 지연시켜 성공할 때까지 재시도한다(비블로킹).
    scwin.wf_insertGenChild = function (tryCount) {
        scwin.generator1.insertChildAsync().then(function () {
            // generator 는 insert 시 자식 clone 의 id 를 재생성하므로 getChild(index, originalId) 로 조회 후 윈도우 생성
            let childWC = scwin.generator1.getChild(0, "generator1_child");
            if (childWC) {
                childWC.createWindow({
                    title : "windowContainer_link_1",
                    src : "/sample/common_link/windowContainer_link_1.xml",
                    windowTitle : "GENERATOR CHILD",
                    windowId : "test001",
                    openAction : "selectWindow"
                });
            }
        }).catch(function () {
            if (tryCount > 0) {
                setTimeout(function () { scwin.wf_insertGenChild(tryCount - 1); }, 100);
            }
        });
    };
    setTimeout(function () { scwin.wf_insertGenChild(20); }, 100);

    // Generator 컴포넌트의 자식이 아닌 standalone windowContainer(target1) 생성
    //  Window 생성은 createBasicWindowContainer 내부에서 처리한다.
    await $c.gcm.createBasicWindowContainer('', 'ev:onclick="scwin.target1_onclick"');
}
